  public static object LastCompositionReceipt{get;private set;}
  static BigInteger Cross(Point64 a,Point64 b,Point64 c)=>(BigInteger)(b.X-a.X)*(c.Y-a.Y)-(BigInteger)(b.Y-a.Y)*(c.X-a.X);
  static double Distance(Point64 p,Point64 a,Point64 b,out double t){double dx=b.X-a.X,dz=b.Y-a.Y,length=dx*dx+dz*dz;t=length==0?0:((p.X-a.X)*dx+(p.Y-a.Y)*dz)/length;double f=Math.Max(0,Math.Min(1,t));return Math.Sqrt(Math.Pow(p.X-a.X-f*dx,2)+Math.Pow(p.Y-a.Y-f*dz,2));}
  public static LocalTerrainMesh[] Build(int cellX,int cellZ,double originY,RoadTerrainSource source,ManagedTerrainMesh terrain,IReadOnlyList<IReadOnlyList<TerrainPoint>> exposedMask,out Dictionary<string,string[]> members){long scale=ManagedTerrainDomainLocal.Scale;double ox=cellX*32.0,oz=cellZ*32.0;long oxq=cellX*32L*scale,ozq=cellZ*32L*scale;var rect=new Rect64(oxq,ozq,oxq+32*scale,ozq+32*scale);var polygons=new List<Polygon>();foreach(var triangle in source.SelectCell(cellX,cellZ,0)){var path=new Path64(triangle.Points.Select(p=>new Point64((long)Math.Round(p.X*scale),(long)Math.Round(p.Z*scale))));if(Clipper.Area(path)<0)path.Reverse();var clipped=Clipper.RectClip(rect,new Paths64{path});foreach(var ring in clipped){if(ring.Count<3||Clipper.Area(ring)==0)throw new ArgumentException("Clipped physical asphalt primitive collapsed; no deletion");polygons.Add(new Polygon{Packet=triangle.PacketId,Points=ring.ToList(),FlatY=triangle.Points.All(p=>p.Y==triangle.Points[0].Y)?triangle.Points[0].Y:(double?)null});}}var aliases=new Dictionary<string,string[]>();var rawPackets=source.CopyPackets().ToDictionary(p=>p.Id);var coalescence=new List<object>();foreach(var group in polygons.Where(p=>p.FlatY.HasValue).GroupBy(p=>p.FlatY.Value).ToArray()){
    var flat=group.ToArray();if(flat.Length<2)continue;var union=new Paths64();double inputArea=0;foreach(var polygon in flat)inputArea+=Math.Abs(Clipper.Area(new Path64(polygon.Points)))/(scale*(double)scale);for(int first=0;first<flat.Length;first+=128){var batch=new Paths64(union);batch.AddRange(flat.Skip(first).Take(128).Select(p=>new Path64(p.Points)));if(batch.Sum(p=>p.Count)>8192)throw new ArgumentException("Coplanar owner union budget");union=Clipper.Union(batch,FillRule.NonZero);}if(Clipper.Triangulate(union,out var tris,true)!=TriangulateResult.success)throw new ArgumentException("Coplanar owner CDT failed without removingcoverage");string alias="coplanar-owner/"+BitConverter.DoubleToInt64Bits(group.Key).ToString("x16");var originalPackets=flat.Select(p=>p.Packet).Distinct().OrderBy(p=>p,StringComparer.Ordinal).ToArray();aliases[alias]=originalPackets.SelectMany(p=>rawPackets[p].RoadMembers).Distinct().OrderBy(p=>p,StringComparer.Ordinal).ToArray();double unionArea=Math.Abs(Clipper.Area(union))/(scale*(double)scale);coalescence.Add(new{owner=alias,sourcePacketIds=originalPackets,memberRoadIds=aliases[alias],originalTriangles=flat.Length,finalOwnerTriangles=tris.Count,originalCoverageSum=inputArea,physicalUnionArea=unionArea,removedDuplicateCoverageArea=inputArea-unionArea,exactSharedPlaneY=group.Key,meaning="Identical coplanar owner composition, not numerical-artifact cleanup or mapped-feature removal"});foreach(var polygon in flat)polygons.Remove(polygon);foreach(var tri in tris)polygons.Add(new Polygon{Packet=alias,Points=tri.ToList(),FlatY=group.Key});}
   LastCompositionReceipt=new{recipe="ExactFlatOwnerComposition1",groups=coalescence};
   if(polygons.Count>32768)throw new ArgumentException("Joined asphalt polygon cap");var sourceContours=exposedMask.Select(p=>p.Select(q=>new Point64((long)Math.Round(q.X*scale),(long)Math.Round(q.Z*scale))).ToArray()).ToArray();bool Exposed(Point64 a,Point64 b){var middle=new Point64((a.X+b.X)/2,(a.Y+b.Y)/2);foreach(var path in sourceContours)for(int i=0;i<path.Length;i++)if(Distance(middle,path[i],path[(i+1)%path.Length],out _)<=.00002*scale)return true;return false;}
   var terrainEdges=new Dictionary<TerrainMeshEdge,int>();for(int i=0;i<terrain.Triangles.Length;i+=3){int a=terrain.Triangles[i],b=terrain.Triangles[i+1],c=terrain.Triangles[i+2];foreach(var edge in new[]{new TerrainMeshEdge(a,b),new TerrainMeshEdge(b,c),new TerrainMeshEdge(c,a)}){terrainEdges.TryGetValue(edge,out int n);terrainEdges[edge]=n+1;}}var required=new HashSet<(long,long)>();foreach(var pair in terrainEdges.Where(p=>p.Value==1)){foreach(int id in new[]{pair.Key.A,pair.Key.B}){var p=terrain.Vertices[id];required.Add((oxq+(long)Math.Round(p.X*scale),ozq+(long)Math.Round(p.Z*scale)));}}var existing=new HashSet<(long,long)>(polygons.SelectMany(p=>p.Points).Select(p=>(p.X,p.Y)));var inserted=new Dictionary<(int,int),List<Point64>>();foreach(var key in required){if(existing.Contains(key))continue;var point=new Point64(key.Item1,key.Item2);double best=double.PositiveInfinity;var matches=new List<(int,int)>();for(int pi=0;pi<polygons.Count;pi++){var polygon=polygons[pi];for(int ei=0;ei<polygon.Points.Count;ei++){var a=polygon.Points[ei];var b=polygon.Points[(ei+1)%polygon.Points.Count];double distance=Distance(point,a,b,out double t);if(t<=0||t>=1||distance>.00002*scale||!Exposed(a,b))continue;if(distance<best-1e-8){best=distance;matches.Clear();matches.Add((pi,ei));}else if(Math.Abs(distance-best)<=1e-8)matches.Add((pi,ei));}}if(matches.Count==0){ // Ordinary terrain-only outer-cell knots are not road obligations.
     if(point.X==oxq||point.X==oxq+32*scale||point.Y==ozq||point.Y==ozq+32*scale)continue;throw new ArgumentException("Final source-boundary terrain knot lacks asphalt owner");}foreach(var match in matches){if(!inserted.TryGetValue(match,out var list))inserted[match]=list=new List<Point64>();list.Add(point);}}
   var allPoints=new HashSet<(long,long)>(existing);foreach(var p in required)allPoints.Add(p);var pointGrid=new Dictionary<(int,int),List<Point64>>();foreach(var key in allPoints){int x=(int)Math.Floor((double)(key.Item1-oxq)/scale),z=(int)Math.Floor((double)(key.Item2-ozq)/scale);if(!pointGrid.TryGetValue((x,z),out var list))pointGrid[(x,z)]=list=new List<Point64>();list.Add(new Point64(key.Item1,key.Item2));}var output=new Dictionary<string,(List<float> XYZ,List<int> Indices,Dictionary<(long,long),int> Weld)>();int visits=0;
   for(int pi=0;pi<polygons.Count;pi++){var polygon=polygons[pi];var restored=new List<Point64>();for(int ei=0;ei<polygon.Points.Count;ei++){var a=polygon.Points[ei];var b=polygon.Points[(ei+1)%polygon.Points.Count];var extras=new HashSet<(long,long)>();if(inserted.TryGetValue((pi,ei),out var additions))foreach(var p in additions)extras.Add((p.X,p.Y));for(int z=(int)Math.Floor((double)(Math.Min(a.Y,b.Y)-ozq)/scale);z<=(int)Math.Floor((double)(Math.Max(a.Y,b.Y)-ozq)/scale);z++)for(int x=(int)Math.Floor((double)(Math.Min(a.X,b.X)-oxq)/scale);x<=(int)Math.Floor((double)(Math.Max(a.X,b.X)-oxq)/scale);x++)if(pointGrid.TryGetValue((x,z),out var list))foreach(var p in list){if(++visits>8000000)throw new ArgumentException("Asphalt global knotclosure workcap");if((p.X==a.X&&p.Y==a.Y)||(p.X==b.X&&p.Y==b.Y))continue;if(Cross(a,b,p).IsZero&&p.X>=Math.Min(a.X,b.X)&&p.X<=Math.Max(a.X,b.X)&&p.Y>=Math.Min(a.Y,b.Y)&&p.Y<=Math.Max(a.Y,b.Y))extras.Add((p.X,p.Y));}restored.Add(a);restored.AddRange(extras.Select(p=>new Point64(p.Item1,p.Item2)).OrderBy(p=>(BigInteger)(p.X-a.X)*(b.X-a.X)+(BigInteger)(p.Y-a.Y)*(b.Y-a.Y)));}if(restored.Count>4096||restored.Select(p=>(p.X,p.Y)).Distinct().Count()!=restored.Count)throw new ArgumentException("Asphalt restored ring self-touch/cap");BigInteger area=0;for(int i=0;i<restored.Count;i++){var a=restored[i];var b=restored[(i+1)%restored.Count];area+=(BigInteger)a.X*b.Y-(BigInteger)a.Y*b.X;}if(area.IsZero)throw new ArgumentException("Asphalt positive primitive collapsed");if(area.Sign>0)restored.Reverse();string id=polygon.Packet+"/cell/"+cellX+"/"+cellZ;if(!output.TryGetValue(id,out var buffers))output[id]=buffers=(new List<float>(),new List<int>(),new Dictionary<(long,long),int>());int V(Point64 p){var key=(p.X,p.Y);if(buffers.Weld.TryGetValue(key,out int index))return index;index=buffers.XYZ.Count/3;double x=(double)p.X/scale,z=(double)p.Y/scale;if(!source.Pavement(x,z,out double y,out _,out _))throw new ArgumentException("Final asphalt knot lacks sourceplane");buffers.Weld.Add(key,index);buffers.XYZ.Add((float)(x-ox));buffers.XYZ.Add((float)(y-originY));buffers.XYZ.Add((float)(z-oz));return index;}
    var pending=new List<Point64>(restored);while(pending.Count>3){bool clipped=false;for(int i=0;i<pending.Count;i++){var a=pending[(i+pending.Count-1)%pending.Count];var b=pending[i];var c=pending[(i+1)%pending.Count];if(Cross(a,b,c).Sign>=0)continue;bool contains=false;for(int j=0;j<pending.Count;j++){var p=pending[j];if((p.X==a.X&&p.Y==a.Y)||(p.X==b.X&&p.Y==b.Y)||(p.X==c.X&&p.Y==c.Y))continue;if(Cross(a,b,p).Sign<=0&&Cross(b,c,p).Sign<=0&&Cross(c,a,p).Sign<=0){contains=true;break;}}if(contains)continue;buffers.Indices.AddRange(new[]{V(a),V(b),V(c)});pending.RemoveAt(i);clipped=true;break;}if(!clipped)throw new ArgumentException("Asphalt ear cannot preserve all positive/collinear source controls");}if(Cross(pending[0],pending[1],pending[2]).Sign>=0)throw new ArgumentException("Asphalt final ear degenerate/backward");buffers.Indices.AddRange(pending.Select(V));}
   var original=source.CopyPackets().ToDictionary(p=>p.Id);members=new Dictionary<string,string[]>();var meshes=new List<LocalTerrainMesh>();foreach(var pair in output.OrderBy(p=>p.Key,StringComparer.Ordinal)){string sourceId=pair.Key.Substring(0,pair.Key.LastIndexOf("/cell/",StringComparison.Ordinal));members[pair.Key]=aliases.TryGetValue(sourceId,out var aliasMembers)?(string[])aliasMembers.Clone():(string[])original[sourceId].RoadMembers.Clone();meshes.Add(new LocalTerrainMesh(pair.Key,ox,originY,oz,pair.Value.XYZ.ToArray(),pair.Value.Indices.ToArray()));}return meshes.ToArray();
  }
 }
